def truncate(text, max_len=50, ellipsis='...'):
    if len(text) <= max_len:
        return text
    cut = text[:max_len - len(ellipsis)]
    if ' ' in cut:
        cut = cut[:cut.rfind(' ')]
    return cut.rstrip() + ellipsis

