def count_vowels_consonants(text):
    vowels = consonants = 0
    for ch in text.lower():
        if ch in 'aeiou':
            vowels += 1
        elif ch.isalpha():
            consonants += 1
    return {'vowels': vowels, 'consonants': consonants}

