def title_case(sentence):
    small = {'a', 'an', 'the', 'of', 'in', 'on', 'and', 'or', 'to'}
    words = sentence.lower().split()
    out = [w.capitalize() for i, w in enumerate(words) if i == 0 or w not in small]
    return ' '.join(out)

print(title_case('the history of time and space'))

def run_length_encode(text):
    if not text:
        return ''
    result, count, prev = [], 1, text[0]
    for ch in text[1:]:
        if ch == prev:
            count += 1
        else:
            result.append(str(count) + prev)
            prev, count = ch, 1
    result.append(str(count) + prev)
    return ''.join(result)

print(run_length_encode('aaabbbcc'))

